cp .build/release/RagdollService "$stage/Contents/MacOS/RagdollService"
mkdir -p "$stage/Contents/Library/LaunchAgents"
cp packaging/com.oyamameek.ragdoll.service.plist "$stage/Contents/Library/LaunchAgents/"
